/* Plain-double tail of ln(1+z): Q(z) = (ln(1+z) - z)/z^2, low-degree first.
 * Degree 7 over |z| <= 2^-7.484: the truncation past z^7, scaled by z^2, is
 * z^10/10 <= 2^-78 -- far under the leg's 2^-66 budget. */
static const double lncells_q_[8] = {
    -0.5,
    0.3333333333333333,
    -0.25,
    0.2,
    -0.16666666666666666,
    0.14285714285714285,
    -0.125,
    0.1111111111111111
};

/* Decompose a finite positive x = 2^e * m (m in [1, 2)) into e, the
 * 7-bit-indexed cell, and the exact z = r*m - 1 -- a table load and integer
 * ops, with no double-double residual to carry.  Returns z. */
static inline double lncells_reduce_(double x, int64_t *e_out, const lncells_cell_ **cell_out)
{
    int bias = 0;

    if (x < 0x1p-1022) {           /* normalize subnormals */
        x *= 0x1p54;
        bias = -54;
    }

    int64_t bits = reinterpret(int64_t, x);
    *e_out = ((bits >> 52) & 0x7FF) - 1023 + bias;
    const lncells_cell_ *cell = &lncells_[(bits >> (52 - 7)) & 127];
    *cell_out = cell;

    int64_t m = (bits & 0x000FFFFFFFFFFFFFLL) | ((int64_t)1 << 52);
    int64_t k = (int64_t)(cell->r * 256);   /* exact: r = k/256 */
    return (double)(k * m - ((int64_t)1 << 60)) * 0x1p-60;
}

/* Assemble ln(2^e * m) = e*ln2 + (l1 + l2) + ln(1+z) as an UNNORMALIZED pair:
 * hi is the correctly rounded sum of the dominant terms, lo (<~ 2^-15) carries
 * the rest, and hi + lo is good to < 2^-66 absolute -- the bound the callers'
 * 2^-63 Ziv gates assume, with an 8x margin.
 *
 * The dominant chain commits no error: e*ln2_hi is exact (ln2_hi is a multiple
 * of 2^-42 with a 42-bit significand and |e| <= 1074 < 2^11, so the product
 * needs < 2^53 bits), adding l1 stays exact (both on the 2^-42 grid,
 * |sum| < 746 < 2^11), and the Fast2Sum with the exact z is valid because the
 * generator certifies |e*ln2_hi + l1| is zero or >= max|z| for every reachable
 * pair (tight cases per cell: e = 0, slack 7.6e-6; e = -1, slack 3.8e-3).
 *
 * The rest is the plain-double tail, off the exact path: Horner on lncells_q_
 * (~2^-54 on Q, dominated by the final add against -1/2; scaled by
 * z^2 <= 2^-14.97 -> ~2^-69), rounding z*z and (z*z)*Q (~2^-69 each), the two
 * lo-word adds (~2^-68 each), the 2^-96 table split and e times the 2^-88 ln2
 * split (<= 2^-78).  Replacing metallic-rs's closing fma(e, ln2_lo, low) with
 * a plain product-plus-add costs one extra rounding of e*ln2_lo, at most
 * ulp(1074 * 2^-44)/2 = 2^-87 -- negligible against the 2^-63 gates. */
static inline exptab_sum_ lncells_assemble_(double e, const lncells_cell_ *cell, double z)
{
    double q = lncells_q_[7];
    for (int k = 6; k >= 0; --k)
        q = q * z + lncells_q_[k];

    double tail = (z * z) * q;
    exptab_sum_ s = exptab_fast2sum_(e * logtab_ln2_hi_ + cell->l1, z);
    double low = tail + (s.lo + cell->l2);
    return (exptab_sum_){ s.hi, e * logtab_ln2_lo_ + low };
}

/* The lean leg end to end: the raw unnormalized pair the Ziv gates consume. */
static inline exptab_sum_ lncells_ln_(double x)
{
    int64_t e;
    const lncells_cell_ *cell;
    double z = lncells_reduce_(x, &e, &cell);
    return lncells_assemble_((double)e, cell, z);
}

/* The lean leg on the exact split 1 + x = s + c (log1p and its base-2/10
 * lifts): with delta = c*2^-e the true mantissa is m + delta, so the true
 * reduced argument is z + r*delta; |c| <= ulp(s)/2 makes dz = r*delta <=
 * 2^-53, and its first-order image through ln, dz/(1+z), is dz*(1-z) up to
 * a dropped dz*z^2 <= 2^-68 -- inside the gates' margins.  Plain ops
 * replace metallic-rs's fast_mul_add(-dz, z, dz): rounding dz*z (<= 2^-113)
 * and the subtraction (<= 2^-106) are negligible against them. */
static inline exptab_sum_ lncells_ln1p_raw_(double s, double c)
{
    int64_t e;
    const lncells_cell_ *cell;
    double z = lncells_reduce_(s, &e, &cell);
    double delta = e > -1000 ? c * shift_(1.0, -e) : 0.0;
    double dz = cell->r * delta;
    exptab_sum_ f = lncells_assemble_((double)e, cell, z);

    f.lo += dz - dz * z;
    return f;
}

